steps.raw:
SELECT `School Name`, CDSCode
FROM frpm
WHERE `School Type` = 'Continuation School';

SELECT CDSCode, `School Name`, `Enrollment (K-12)` - `Enrollment (Ages 5-17)` AS enrollment_difference
FROM frpm
WHERE `Enrollment (K-12)` - `Enrollment (Ages 5-17)` > 30;

SELECT CDSCode, `FRPM Count (Ages 5-17)`
FROM frpm
WHERE `FRPM Count (Ages 5-17)` > 800;

SELECT School, Phone
FROM schools
WHERE OpenDate > '1991-12-31' OR ClosedDate < '2000-01-01';

SELECT CDSCode, `Free Meal Count (Ages 5-17)`
FROM frpm
WHERE `Free Meal Count (Ages 5-17)` BETWEEN 1900 AND 2000;

SELECT CDSCode
FROM schools
WHERE AdmFName1 = 'Kacey' OR AdmFName2 = 'Kacey' OR AdmFName3 = 'Kacey';

SELECT `Free Meal Count (Ages 5-17)` / `Enrollment (Ages 5-17)` AS free_rate
FROM frpm
WHERE `School Name` = 'Kacey Gibson' OR CDSCode IN (
    SELECT CDSCode FROM schools WHERE AdmFName1 = 'Kacey' AND AdmLName1 = 'Gibson'
);

SELECT `School Name`, `Free Meal Count (K-12)`, `Enrollment (K-12)`
FROM frpm
WHERE `County Name` = 'Los Angeles';

