steps.raw:
SELECT
  (SELECT COUNT(*) FROM bond WHERE molecule_id = 'TR006' AND bond_type = ' = ') AS double_bond_count,
  (SELECT label FROM molecule WHERE molecule_id = 'TR006') AS label;

SELECT
  (SELECT COUNT(DISTINCT molecule_id) FROM bond WHERE bond_type = ' = ') AS total_molecules_with_double_bond,
  (SELECT COUNT(DISTINCT m.molecule_id) FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE b.bond_type = ' = ' AND m.label = '+') AS carcinogenic_molecules_with_double_bond;

SELECT (SUM(CASE WHEN isOnlineOnly = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(id)) AS percentage
FROM cards
WHERE frameEffects = 'legendary';

WITH total AS (
  SELECT COUNT(id) AS cnt FROM cards
),
spotlight_textless AS (
  SELECT COUNT(id) AS cnt FROM cards WHERE isStorySpotlight = 1 AND isTextless = 0
),
ids AS (
  SELECT id FROM cards WHERE isStorySpotlight = 1 AND isTextless = 0
)
SELECT
  (SELECT cnt FROM spotlight_textless) * 100.0 / (SELECT cnt FROM total) AS percentage,
  (SELECT GROUP_CONCAT(id) FROM ids) AS ids
FROM total;

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM foreign_data
    WHERE language = 'Korean'
      AND uuid IN (SELECT uuid FROM cards WHERE name = 'Ancestor''s Chosen')
) THEN 1 ELSE 0 END AS has_korean_version;

SELECT DISTINCT c.setCode
FROM cards c
WHERE c.name = 'Adarkar Valkyrie';

SELECT votes.*
FROM votes
WHERE votes.BountyAmount = 50;

SELECT PostId, COUNT(*) AS VoteCount
FROM votes
GROUP BY PostId;

WITH male_count AS (
    SELECT COUNT(*) AS cnt FROM superhero WHERE gender_id = 1
),
female_count AS (
    SELECT COUNT(*) AS cnt FROM superhero WHERE gender_id = 2
)
SELECT CAST(male_count.cnt AS REAL) / female_count.cnt AS ratio
FROM male_count, female_count;

SELECT ABS(
  SUM(CASE WHEN p.publisher_name = 'DC Comics' THEN 1 ELSE 0 END) -
  SUM(CASE WHEN p.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END)
) AS difference
FROM superhero s
JOIN publisher p ON s.publisher_id = p.id;

SELECT s.superhero_name
FROM superhero s
WHERE s.height_cm > (SELECT AVG(height_cm) * 0.8 FROM superhero);

SELECT raceId, driverId
FROM lapTimes
WHERE milliseconds = (SELECT MIN(milliseconds) FROM lapTimes);

SELECT league_id, COUNT(*) AS match_count
FROM Match
GROUP BY league_id;

SELECT league_id, SUM(home_team_goal + away_team_goal) AS total_goals
FROM Match
GROUP BY league_id;

SELECT player_api_id, player_name
FROM Player
WHERE height > 180;

SELECT player_api_id, AVG(heading_accuracy) AS avg_heading_accuracy
FROM Player_Attributes
GROUP BY player_api_id;

SELECT overall_rating
FROM Player_Attributes
WHERE CAST(strftime('%Y', date) AS INTEGER) BETWEEN 2010 AND 2015;

SELECT player_name
FROM Player
WHERE (strftime('%Y', 'now') - strftime('%Y', birthday)) - (strftime('%m-%d', 'now') < strftime('%m-%d', birthday)) <= 30;

SELECT 
  (SELECT COUNT(ID) FROM Patient WHERE Diagnosis = 'SLE' AND Admission = '+') * 1.0 /
  (SELECT COUNT(ID) FROM Patient WHERE Diagnosis = 'SLE' AND Admission = '-') AS ratio;

WITH positive_coag AS (
    SELECT DISTINCT ID FROM Examination WHERE RVVT = '+'
),
patient_age AS (
    SELECT ID, CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', Birthday) AS INTEGER) AS age
    FROM Patient
)
SELECT pa.ID, pa.age
FROM patient_age pa
JOIN positive_coag pc ON pa.ID = pc.ID;

SELECT DISTINCT Diagnosis
FROM Examination
WHERE `Examination Date` BETWEEN '1985-01-01' AND '1995-12-31';

SELECT ID, MAX(Date) AS latest_date
FROM Laboratory
GROUP BY ID;

SELECT p.ID
FROM Patient p
WHERE (CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER)) < 50;

SELECT DISTINCT p.ID
FROM Patient p
WHERE (CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER)) < 70;

SELECT link_to_event AS event_id, COUNT(link_to_member) AS attendance_count
FROM attendance
GROUP BY link_to_event;

SELECT (SUM(e.cost) * 100.0 / COUNT(DISTINCT ev.event_id)) AS percentage
FROM event ev
JOIN expense e ON e.link_to_budget IN (
    SELECT budget_id FROM budget WHERE link_to_event = ev.event_id
)
WHERE ev.type = 'Meeting';

SELECT link_to_member, SUM(cost) AS total_cost
FROM expense
GROUP BY link_to_member;

SELECT CustomerID, Consumption
FROM yearmonth
WHERE Date = '201310';

SELECT
  (SELECT SUM(Price) FROM transactions_1k WHERE CustomerID = 38508) AS TotalSpent,
  (SELECT SUM(Price) FROM transactions_1k WHERE CustomerID = 38508 AND Date = '201201') AS SpentJanuary2012;
